def transform(g):
    h,w=len(g),len(g[0]); out=[[0]*w for _ in range(h)]
    blocks=[(r,c) for r in range(h-1) for c in range(w-1)
            if g[r][c] not in (0,3,6,7,8) and all(g[r+dr][c+dc]==g[r][c] for dr in (0,1) for dc in (0,1))]
    bset={(r+dr,c+dc) for r,c in blocks for dr in (0,1) for dc in (0,1)}
    for r,c in blocks:
        cr,cc=r+0.5,c+0.5
        for mr,mc,v in [(i,j,g[i][j]) for i in range(h) for j in range(w) if g[i][j] in (3,6,7,8)]:
            dr,dc=mr-cr,mc-cc
            if abs(abs(dr)-abs(dc))>1e-9: continue
            ndr,ndc=dc,-dr  # rotate 90 CW
            i,j=round(cr+ndr),round(cc+ndc)
            if not (0<=i<h and 0<=j<w) or (i,j) in bset: continue
            s=(1 if ndr>0 else -1,1 if ndc>0 else -1)
            # walk back to cell adjacent to block, then forward to edge
            while (i-s[0],j-s[1]) not in bset and 0<=i-s[0]<h and 0<=j-s[1]<w and (i-s[0],j-s[1]) not in [(mr,mc)]:
                if (i-s[0],j-s[1]) in bset: break
                i-=s[0]; j-=s[1]
                if not(0<=i<h and 0<=j<w): break
            # ensure i,j is the cell adjacent to block
            while 0<=i-s[0]<h and 0<=j-s[1]<w and (i-s[0],j-s[1]) not in bset:
                i-=s[0]; j-=s[1]
            while 0<=i<h and 0<=j<w:
                out[i][j]=v; i+=s[0]; j+=s[1]
    for r,c in blocks:
        for dr in (0,1):
            for dc in (0,1): out[r+dr][c+dc]=g[r][c]
    return out
